import re

def parse_ini(content: str) -> dict:
    """
    Lee un string de contenido INI, filtra líneas vacías y comentarios,
    extrae pares clave-valor y devuelve un diccionario.

    :param content: String conteniendo el contenido del archivo INI.
    :return: Diccionario con las claves y sus valores (convertidos a tipos apropiados).
    """
    result = {}
    lines = content.splitlines()

    for line in lines:
        # 1. Filtrar líneas vacías
        if not line.strip():
            continue

        # 2. Filtrar comentarios (asumiendo que comienzan con #)
        if line.strip().startswith('#'):
            continue

        # 3. Extraer el par clave-valor
        # Buscamos el primer '=' en la línea
        if '=' not in line:
            # Si no hay '=', ignoramos la línea para ser robustos
            continue

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        # Si la clave está vacía, saltamos
        if not key:
            continue

        # 4. Convertir el valor a su tipo correspondiente
        # Intentamos convertir primero a entero, luego a float, luego a booleano, y finalmente a string
        try:
            # Intentar entero
            if value.lower() in ('true', 'false'):
                result[key] = value.lower() == 'true'
            elif value.isdigit() or (value.startswith('-') and value[1:].isdigit()):
                result[key] = int(value)
            else:
                # Intentar flotante
                result[key] = float(value)
            else:
                # Si no es un número ni booleano, asumimos string
                result[key] = value

        except ValueError:
            # Si la conversión falla, mantenemos el valor como string
            result[key] = value

    return result

def get_valor_tipado(config, clave, tipo):
    """
    Recibe el dict que devuelve parse_ini, una clave, y un tipo (int, float, bool o str),
    y devuelve el valor convertido a ese tipo.

    :param config: Diccionario con las claves y valores parseados.
    :param clave: Clave a buscar.
    :param tipo: Tipo de conversión deseado (int, float, bool, str).
    :return: El valor convertido al tipo especificado.
    :raises KeyError: Si la clave no existe.
    :raises TypeError: Si el tipo no es válido.
    """
    if clave not in config:
        raise KeyError(f"La clave '{clave}' no existe en la configuración.")

    if tipo not in (int, float, bool, str):
        raise TypeError(f"Tipo de conversión inválido. Debe ser int, float, bool o str.")

    valor_original = config[clave]

    try:
        if tipo == int:
            return int(valor_original)
        elif tipo == float:
            return float(valor_original)
        elif tipo == bool:
            # Manejo especial para strings booleanos
            if isinstance(valor_original, str):
                return valor_original.lower() in ('true', '1', 'yes')
            elif isinstance(valor_original, (int, float)):
                return bool(valor_original)
            else:
                return bool(valor_original)
        elif tipo == str:
            return str(valor_original)
    except (ValueError, TypeError) as e:
        raise TypeError(f"Error al convertir '{clave}' a {tipo}: {e}")

# --- Ejemplo de uso ---
if __name__ == "__main__":
    input_ini = """
    # Configuración de la aplicación
    app_name = MiApp
    version = 1.5
    debug = true
    max_users = 100
    price = 29.99
    # Fin de la configuración

    database_host = localhost
    database_port = 5432
    """

    config = parse_ini(input_ini)

    print("Configuración parseada:")
    for key, value in config.items():
        print(f"{key}: {value} (tipo: {type(value).__name__})")

    print("\nEjemplo de uso de get_valor_tipado:")
    print(f"max_users (int): {get_valor_tipado(config, 'max_users', int)}")
    print(f"price (float): {get_valor_tipado(config, 'price', float)}")
    print(f"debug (bool): {get_valor_tipado(config, 'debug', bool)}")
    print(f"app_name (str): {get_valor_tipado(config, 'app_name', str)}")
